package edu.smartstudy.quiz;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="quizzes")public class Quiz{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="owner_id",nullable=false)private Long ownerId;@Column(name="material_id",nullable=false)private Long materialId;@Column(nullable=false)private String title;@Column(name="questions_json",nullable=false,columnDefinition="MEDIUMTEXT")private String questionsJson;@Column(name="created_at",insertable=false,updatable=false)private Instant createdAt;protected Quiz(){}public Quiz(Long owner,Long material,String title,String questions){ownerId=owner;materialId=material;this.title=title;questionsJson=questions;}public Long getId(){return id;}public Long getOwnerId(){return ownerId;}public Long getMaterialId(){return materialId;}public String getTitle(){return title;}public String getQuestionsJson(){return questionsJson;}public Instant getCreatedAt(){return createdAt;}}
